package com.orderflow.auth;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import jakarta.persistence.*;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.*;import org.springframework.boot.autoconfigure.*;import org.springframework.context.annotation.*;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.http.*;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.time.*;import java.util.*;
@SpringBootApplication public class AuthApplication{public static void main(String[]a){SpringApplication.run(AuthApplication.class,a);}}
@Entity @Table(name="users",schema="auth") class User{@Id UUID id;@Column(unique=true,nullable=false)String email;@Column(name="password_hash",nullable=false)String passwordHash;@Enumerated(EnumType.STRING)Role role;@Column(name="created_at")Instant createdAt;protected User(){}User(String e,String p){id=UUID.randomUUID();email=e.toLowerCase();passwordHash=p;role=Role.CUSTOMER;createdAt=Instant.now();}enum Role{CUSTOMER,ADMIN}}
@Entity @Table(name="refresh_tokens",schema="auth") class RefreshToken{@Id UUID id;@Column(name="user_id")UUID userId;@Column(name="token_hash",unique=true)String tokenHash;@Column(name="expires_at")Instant expiresAt;boolean revoked;protected RefreshToken(){}RefreshToken(UUID u,String h,Instant x){id=UUID.randomUUID();userId=u;tokenHash=h;expiresAt=x;}}
interface UserRepo extends JpaRepository<User,UUID>{Optional<User>findByEmail(String e);}interface TokenRepo extends JpaRepository<RefreshToken,UUID>{Optional<RefreshToken>findByTokenHashAndRevokedFalse(String h);}
@Configuration class SecurityConfig{@Bean PasswordEncoder encoder(){return new BCryptPasswordEncoder(12);}@Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/actuator/health","/v3/api-docs/**","/swagger-ui/**").permitAll().anyRequest().authenticated()).build();}}
@Service class AuthService{private final UserRepo users;private final TokenRepo tokens;private final PasswordEncoder encoder;private final byte[] secret;private final long accessMinutes,refreshDays;AuthService(UserRepo u,TokenRepo t,PasswordEncoder e,@Value("${jwt.secret}")String s,@Value("${jwt.access-minutes}")long am,@Value("${jwt.refresh-days}")long rd){users=u;tokens=t;encoder=e;secret=s.getBytes(StandardCharsets.UTF_8);accessMinutes=am;refreshDays=rd;}
 @Transactional Tokens register(String email,String password){if(users.findByEmail(email.toLowerCase()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"email already registered");return issue(users.save(new User(email,encoder.encode(password))));}
 @Transactional Tokens login(String email,String password){User u=users.findByEmail(email.toLowerCase()).filter(x->encoder.matches(password,x.passwordHash)).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"invalid credentials"));return issue(u);}
 @Transactional Tokens refresh(String raw){RefreshToken t=tokens.findByTokenHashAndRevokedFalse(hash(raw)).filter(x->x.expiresAt.isAfter(Instant.now())).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"invalid refresh token"));t.revoked=true;return issue(users.findById(t.userId).orElseThrow());}
 private Tokens issue(User u){Instant now=Instant.now(),exp=now.plus(Duration.ofMinutes(accessMinutes));String jwt=Jwts.builder().subject(u.id.toString()).claim("email",u.email).claim("role",u.role.name()).issuedAt(Date.from(now)).expiration(Date.from(exp)).signWith(Keys.hmacShaKeyFor(secret)).compact();String refresh=UUID.randomUUID()+"."+UUID.randomUUID();tokens.save(new RefreshToken(u.id,hash(refresh),now.plus(Duration.ofDays(refreshDays))));return new Tokens(jwt,refresh,"Bearer",accessMinutes*60);}
 private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
@RestController @RequestMapping("/api/auth") class AuthController{private final AuthService service;AuthController(AuthService s){service=s;}record Credentials(@Email @NotBlank String email,@Size(min=8,max=72)String password){}record Refresh(@NotBlank String refreshToken){}@PostMapping("/register")@ResponseStatus(HttpStatus.CREATED)Tokens register(@Valid@RequestBody Credentials r){return service.register(r.email,r.password);}@PostMapping("/login")Tokens login(@Valid@RequestBody Credentials r){return service.login(r.email,r.password);}@PostMapping("/refresh")Tokens refresh(@Valid@RequestBody Refresh r){return service.refresh(r.refreshToken);}}
record Tokens(String accessToken,String refreshToken,String tokenType,long expiresInSeconds){}
